/**
 * @param {string} s
 * @return {number}
 */
var scoreOfParentheses = function(s) {
    const map = new Map([[0, 0]]);
    let depth = 0;

    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            depth++;

            map.set(depth, 0);
        } else {
            depth--;

            const added = s[i - 1] === '(' ? 1 : 2 * map.get(depth + 1);
            map.set(depth, map.get(depth) + added);
        }
    }

    return map.get(0);
};
